-- ---------------------------------------------------------------- functions

-- The customer-facing "find my order" screen. Requires both the id and the phone,
-- so the order number alone leaks nothing.
create or replace function lookup_order(p_order_id text, p_phone text)
returns table (
  id text, customer_name text, state order_state, pay_state pay_state,
  total_cents bigint, pickup_at timestamptz, placed_at timestamptz
)
language sql stable security definer set search_path = public as $$
  select o.id, o.customer_name, o.state, o.pay_state, o.total_cents, d.pickup_at, o.placed_at
  from orders o left join drops d on d.id = o.drop_id
  where o.id = p_order_id
    and regexp_replace(o.phone, '[^0-9]', '', 'g') = regexp_replace(p_phone, '[^0-9]', '', 'g')
  limit 1
$$;

revoke all on function lookup_order(text, text) from public;
grant execute on function lookup_order(text, text) to anon, authenticated;

-- Remaining capacity for a drop. The prototype refuses an order that would take the
-- drop past capacity; enforcing it here means two customers checking out at the same
-- moment cannot both slip through.
create or replace function drop_remaining(p_drop_id uuid)
returns integer
language sql
stable
security definer
set search_path = public
as $$
  -- Only orders that reserve capacity count, per state_reserves_capacity() above, which
  -- is the engine's RESERVING list. A cancelled or no-show order releases its boxes.
  --
  -- The check has to happen inside the insert transaction, not before it: checking and
  -- then inserting is a race, and the race is two customers taking the last box. See
  -- src/lib/rules/capacity.ts and tests/fixtures/capacity-cases.json.
  select greatest(
    0,
    coalesce((select capacity from drops where id = p_drop_id), 0)
      - coalesce((
          select sum(oi.qty)::int
          from orders o
          join order_items oi on oi.order_id = o.id
          where o.drop_id = p_drop_id
            and state_reserves_capacity(o.state)
        ), 0)
  );
$$;

create or replace function touch_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end $$;

create trigger orders_touch before update on orders
for each row execute function touch_updated_at();

-- Idempotent intake for the offline bazaar queue.
--
-- The device sends everything it holds, every time. This function must be safe to call
-- with the same client_id repeatedly: the second call reports the sale as accepted
-- without writing a second row or a second ledger entry.

create or replace function sync_event_sale(p_sale jsonb)
returns table (client_id text, sale_id uuid, duplicate boolean)
language plpgsql security definer set search_path = public as $$
declare
  v_client_id text := p_sale ->> 'clientId';
  v_existing  uuid;
  v_sale_id   uuid;
  v_ledger_id uuid;
  v_item      jsonb;
begin
  if not is_staff() then
    raise exception 'not authorised' using errcode = '42501';
  end if;
  if v_client_id is null or length(v_client_id) = 0 then
    raise exception 'clientId is required' using errcode = '22023';
  end if;

  select es.id into v_existing from event_sales es where es.client_id = v_client_id;
  if v_existing is not null then
    return query select v_client_id, v_existing, true;
    return;
  end if;

  insert into ledger_entries (kind, category, memo, amount_cents, occurred_at, created_by)
  values (
    'sale', 'Bazaar', 'Stall sale ' || v_client_id,
    (p_sale ->> 'total')::numeric * 100,
    to_timestamp((p_sale ->> 'at')::bigint / 1000.0),
    auth.uid()
  )
  returning id into v_ledger_id;

  insert into event_sales (
    client_id, event_id, gross_cents, discount_cents, total_cents,
    pay_method, pay_ref, tendered_cents, change_cents, clerk, sold_at, ledger_id
  ) values (
    v_client_id,
    nullif(p_sale ->> 'eventId', '')::uuid,
    (p_sale ->> 'gross')::numeric * 100,
    coalesce((p_sale ->> 'discount')::numeric, 0) * 100,
    (p_sale ->> 'total')::numeric * 100,
    coalesce(p_sale ->> 'pay', 'cash'),
    coalesce(p_sale ->> 'ref', ''),
    coalesce((p_sale ->> 'tendered')::numeric, 0) * 100,
    coalesce((p_sale ->> 'change')::numeric, 0) * 100,
    coalesce(p_sale ->> 'clerk', ''),
    to_timestamp((p_sale ->> 'at')::bigint / 1000.0),
    v_ledger_id
  )
  returning id into v_sale_id;

  for v_item in select * from jsonb_each(coalesce(p_sale -> 'items', '{}'::jsonb))
  loop
    insert into event_sale_items (sale_id, product_id, qty, unit_price_cents)
    select v_sale_id, p.id, (v_item -> 1)::text::int, p.price_cents
    from products p where p.id = (v_item -> 0)::text;
  end loop;

  insert into audit_log (actor, action, entity, entity_id, detail)
  values (auth.uid(), 'sale.synced', 'event_sales', v_sale_id::text, p_sale);

  return query select v_client_id, v_sale_id, false;
end $$;

revoke all on function sync_event_sale(jsonb) from public;
grant execute on function sync_event_sale(jsonb) to authenticated;

-- Rate limiting, in Postgres.
--
-- Why not Redis. The usual answer is Upstash, and the usual argument against Postgres is
-- that a rate-limit check consumes the connection you are trying to protect. That
-- argument is real at scale and weak here: this is one baker with a 200-box capacity, the
-- check is a single indexed upsert, and the alternative is a second paid service for a
-- home business to configure and keep credentials for. If traffic ever justifies Redis,
-- src/lib/rate-limit.ts is written to swap its store without callers changing.
--
-- The threat is not load. It is one bored person with a script hitting /shop or
-- /orders/lookup during a drop, and order-number enumeration on lookup.

create table if not exists rate_limits (
  -- bucket key: '<route>:<identifier>' — an IP for public routes, a user id for staff
  key         text not null,
  window_start timestamptz not null,
  count       integer not null default 0,
  primary key (key, window_start)
);

comment on table rate_limits is
  'Fixed-window counters. Rows older than the widest window are dead and pruned by prune_rate_limits().';

-- Only the window currently being written to is ever read, so the primary key is the
-- whole index story. This one is for the pruner.
create index if not exists rate_limits_window_idx on rate_limits (window_start);

/**
 * Consumes one unit from a bucket and reports whether the caller may proceed.
 *
 * A fixed window, not a sliding one: it is one statement, it needs no sorted set, and at
 * this scale the burst a fixed window permits at a boundary is not a problem worth a
 * second service. Returns the remaining allowance and when the window resets so the
 * handler can set the standard headers.
 *
 * SECURITY DEFINER because anon must be able to consume a bucket without being able to
 * read anyone else's counters.
 */
create or replace function consume_rate_limit(
  p_key      text,
  p_limit    integer,
  p_window_s integer
)
returns table (allowed boolean, remaining integer, reset_at timestamptz)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_start timestamptz;
  v_count integer;
begin
  if p_limit <= 0 or p_window_s <= 0 then
    raise exception 'consume_rate_limit: limit and window must be positive';
  end if;

  -- Truncate now() to the window, so every caller in the same window agrees on the key.
  v_start := to_timestamp(floor(extract(epoch from now()) / p_window_s) * p_window_s);

  insert into rate_limits (key, window_start, count)
  values (p_key, v_start, 1)
  on conflict (key, window_start)
    do update set count = rate_limits.count + 1
  returning rate_limits.count into v_count;

  return query select
    v_count <= p_limit,
    greatest(p_limit - v_count, 0),
    v_start + make_interval(secs => p_window_s);
end;
$$;

/** Deletes spent windows. Call from a daily cron; nothing depends on the history. */
create or replace function prune_rate_limits()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_deleted integer;
begin
  delete from rate_limits where window_start < now() - interval '2 hours';
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;

alter table rate_limits enable row level security;
-- Nobody reads this table directly. The function is the only door, and it is definer.
revoke all on table rate_limits from anon, authenticated;
grant execute on function consume_rate_limit(text, integer, integer) to anon, authenticated;
grant execute on function prune_rate_limits() to service_role;

